func (s *FileServerService) getMotionPath(attachment *store.Attachment) (string, error) {
	cacheFolder := filepath.Join(s.Profile.Data, MotionCacheFolder)
	if err := os.MkdirAll(cacheFolder, os.ModePerm); err != nil {
